from itertools import product
from typing import Tuple

def enumerate_isolating(n: int, d: int) -> int:
    """Brute-force count of isolating assignments in [d]^n: those w for which a
    unique vertex attains the strict minimum weight. Ground truth reference."""
    if n == 0:
        return 0
    count = 0
    for w in product(range(d), repeat=n):
        m = min(w)
        if sum(1 for x in w if x == m) == 1:
            count += 1
    return count

def closed_form(n: int, d: int) -> int:
    """Exact Count Theorem: n * sum_{j<d} j^(n-1)."""
    if n == 0:
        return 0
    return n * sum(j ** (n - 1) for j in range(d))

if __name__ == "__main__":
    for n in range(0, 5):
        for d in range(1, 6):
            e, c = enumerate_isolating(n, d), closed_form(n, d)
            assert e == c, (n, d, e, c)
            print(f"n={n} d={d}: enum={e:>4}  closed={c:>4}")
    print("All parameters agree: the closed form equals the brute-force count.")

from typing import List

def per_vertex_count(n: int, d: int) -> int:
    """Assignments for which a FIXED vertex is the strict minimum:
    sum_{m<d} (d-1-m)^(n-1) = sum_{k<d} k^(n-1), independent of the vertex."""
    if n == 0:
        return 0
    return sum((d - 1 - m) ** (n - 1) for m in range(d))

def fiber_sizes(n: int, d: int) -> List[int]:
    """Fiber sizes (d-1-m)^(n-1) as the minimum value m ranges over 0..d-1."""
    if n == 0:
        return [0] * d
    return [(d - 1 - m) ** (n - 1) for m in range(d)]

if __name__ == "__main__":
    n, d = 3, 5
    print(f"n={n}, d={d}")
    print("fiber sizes by minimum value m:", fiber_sizes(n, d))
    print("sum over fibers (per-vertex count):", per_vertex_count(n, d))
    print("times n vertices =", n * per_vertex_count(n, d))
    print("closed form       =", n * sum(j ** (n - 1) for j in range(d)))

from itertools import product
from typing import Dict, Tuple

def argmin_partition(n: int, d: int) -> Dict[int, int]:
    """Tabulate isolating assignments by their unique argmin vertex.
    Demonstrates the disjoint decomposition: every part has equal size."""
    counts: Dict[int, int] = {i: 0 for i in range(n)}
    for w in product(range(d), repeat=n):
        m = min(w)
        winners = [i for i, x in enumerate(w) if x == m]
        if len(winners) == 1:
            counts[winners[0]] += 1
    return counts

if __name__ == "__main__":
    for (n, d) in [(3, 4), (4, 3), (2, 5)]:
        parts = argmin_partition(n, d)
        total = sum(parts.values())
        print(f"n={n}, d={d}: per-vertex parts = {parts}, total = {total}")
        assert len(set(parts.values())) == 1, "parts must be equal by symmetry"
        assert total == n * sum(j ** (n - 1) for j in range(d))
    print("Parts are equal and sum to n * sum_{j<d} j^(n-1).")

