from itertools import product

def count_isolating_bruteforce(n: int, d: int) -> int:
    """Count isolating assignments by exhaustive enumeration. O(n * d^n)."""
    if n == 0:
        return 0
    total: int = 0
    for w in product(range(d), repeat=n):
        m: int = min(w)
        if sum(1 for x in w if x == m) == 1:
            total += 1
    return total

def count_isolating_closed_form(n: int, d: int) -> int:
    """Exact Count Theorem evaluator: n * sum_{j=0}^{d-1} j^(n-1).
    O(d) multiplications (O(d log n) with fast powering)."""
    if n == 0:
        return 0
    exponent: int = n - 1
    return n * sum(j ** exponent for j in range(d))

