from typing import List

def isolating_by_fibering(n: int, d: int) -> int:
    """Compute the isolating count via the (argmin vertex, minimum value)
    fibering: sum over n vertices of sum over m<d of (d-1-m)^(n-1)."""
    if n == 0:
        return 0
    per_vertex: int = 0
    for m in range(d):
        per_vertex += (d - 1 - m) ** (n - 1)
    return n * per_vertex
